"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar, MapPin, Filter, ChevronDown, 
  Globe, Sparkles, Flag, Building2, CalendarDays 
} from "lucide-react";

/* --- 1. ENRICHED DATASET --- */
const HOLIDAYS_DB = [
  // --- 2025 ---
  { id: 1, name: "New Year's Day", date: "Jan 01", day: "Wednesday", year: "2025", type: "Public", country: "Global", region: "All" },
  { id: 2, name: "Republic Day", date: "Jan 26", day: "Sunday", year: "2025", type: "National", country: "India", region: "All" },
  { id: 3, name: "Presidents' Day", date: "Feb 17", day: "Monday", year: "2025", type: "Public", country: "USA", region: "All" },
  { id: 4, name: "Holi", date: "Mar 14", day: "Friday", year: "2025", type: "Optional", country: "India", region: "North India" },
  { id: 5, name: "Good Friday", date: "Apr 18", day: "Friday", year: "2025", type: "Public", country: "Global", region: "All" },
  { id: 6, name: "Independence Day", date: "Aug 15", day: "Friday", year: "2025", type: "National", country: "India", region: "All" },
  
  // --- 2026 ---
  { id: 7, name: "New Year's Day", date: "Jan 01", day: "Thursday", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 8, name: "Republic Day", date: "Jan 26", day: "Monday", year: "2026", type: "National", country: "India", region: "All" },
  { id: 9, name: "Ugadi", date: "Mar 19", day: "Thursday", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  { id: 10, name: "Memorial Day", date: "May 25", day: "Monday", year: "2026", type: "Public", country: "USA", region: "All" },
  { id: 11, name: "Kannada Rajyotsava", date: "Nov 01", day: "Sunday", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 12, name: "Christmas", date: "Dec 25", day: "Friday", year: "2026", type: "Public", country: "Global", region: "All" },
];

export default function PremiumHolidayList() {
  // --- STATE ---
  const [yearFilter, setYearFilter] = useState("2026");
  const [countryFilter, setCountryFilter] = useState("All");
  const [locFilter, setLocFilter] = useState("All");
  const [typeFilter, setTypeFilter] = useState("All");

  // --- FILTER ENGINE ---
  const filteredData = useMemo(() => {
    return HOLIDAYS_DB.filter((h) => {
      // 1. Year
      const matchYear = h.year === yearFilter;
      
      // 2. Country (Global applies to everyone)
      const matchCountry = 
        countryFilter === "All" || 
        h.country === countryFilter || 
        h.country === "Global";

      // 3. Region (Show Country-Wide holidays if specific region is selected)
      const matchRegion = 
        locFilter === "All" || 
        h.region === locFilter || 
        h.region === "All";

      // 4. Type
      const matchType = typeFilter === "All" || h.type === typeFilter;

      return matchYear && matchCountry && matchRegion && matchType;
    });
  }, [yearFilter, countryFilter, locFilter, typeFilter]);

  return (
    <div className="min-h-screen bg-[#F8F9FC] dark:bg-[#030712] text-slate-900 dark:text-slate-100 font-sans pb-20">
      
      {/* --- HERO HEADER --- */}
      <div className="bg-white dark:bg-[#0B0F19] border-b border-slate-200 dark:border-slate-800/60 pt-10 pb-16 px-6 lg:px-12">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-end gap-8">
           <div className="space-y-4">
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/5">
                 <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                 <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Live Calendar</span>
              </div>
              <h1 className="text-5xl lg:text-6xl font-black tracking-tighter text-slate-900 dark:text-white uppercase italic">
                Holiday <span className="text-slate-300 dark:text-slate-700">Hub</span>
              </h1>
              <p className="text-sm font-medium text-slate-500 max-w-md">
                Official corporate schedule for fiscal year <span className="text-slate-900 dark:text-white font-bold">{yearFilter}</span> across all operating regions.
              </p>
           </div>

           {/* Stats Widget */}
           <div className="flex gap-2 p-1.5 bg-slate-50 dark:bg-white/5 rounded-2xl border border-slate-200 dark:border-white/5">
              <StatItem label="Total" value={filteredData.length} />
              <div className="w-[1px] bg-slate-200 dark:bg-white/10 my-2" />
              <StatItem label="Public" value={filteredData.filter(h=>h.type!=='Optional').length} />
              <div className="w-[1px] bg-slate-200 dark:bg-white/10 my-2" />
              <StatItem label="Optional" value={filteredData.filter(h=>h.type==='Optional').length} />
           </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 lg:px-12 -mt-8 relative z-10">
        
        {/* --- CONTROL BAR (The "Cockpit") --- */}
        <div className="bg-white dark:bg-[#11151F] p-2 rounded-2xl shadow-xl shadow-slate-200/50 dark:shadow-black/50 border border-slate-100 dark:border-slate-800 flex flex-col lg:flex-row gap-2">
           
           {/* Year */}
           <FilterDropdown 
             icon={<CalendarDays size={14} />} 
             value={yearFilter} 
             onChange={setYearFilter} 
             options={['2025', '2026']} 
           />

           {/* Country */}
           <FilterDropdown 
             icon={<Flag size={14} />} 
             value={countryFilter} 
             onChange={setCountryFilter} 
             options={['All', 'India', 'USA']} 
             placeholder="All Countries"
           />

           {/* Location (Region) */}
           <FilterDropdown 
             icon={<Building2 size={14} />} 
             value={locFilter} 
             onChange={setLocFilter} 
             options={['All', 'Telangana', 'Karnataka', 'North India']} 
             placeholder="All Regions"
           />

           {/* Type Toggle */}
           <div className="bg-slate-50 dark:bg-white/5 rounded-xl p-1 flex">
              {['All', 'Public', 'Optional'].map(t => (
                <button
                  key={t}
                  onClick={() => setTypeFilter(t)}
                  className={`flex-1 px-5 py-2.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                    typeFilter === t 
                    ? "bg-white dark:bg-brand-600 text-slate-900 dark:text-white shadow-sm scale-100" 
                    : "text-slate-400 hover:text-slate-600 dark:hover:text-slate-300"
                  }`}
                >
                  {t}
                </button>
              ))}
           </div>
        </div>

        {/* --- 3-COLUMN GRID LAYOUT --- */}
        <div className="mt-10 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
           {filteredData.length > 0 ? filteredData.map((h) => (
             <div 
               key={h.id}
               className="group bg-white dark:bg-[#11151F] rounded-[2rem] p-6 border border-slate-200 dark:border-slate-800 hover:border-brand-500/50 dark:hover:border-brand-500/50 transition-all duration-300 hover:shadow-2xl hover:shadow-brand-500/5 hover:-translate-y-1 relative overflow-hidden"
             >
                {/* Background Decor */}
                <div className="absolute top-0 right-0 p-8 opacity-[0.03] dark:opacity-[0.05] group-hover:opacity-10 dark:group-hover:opacity-10 transition-opacity transform group-hover:scale-110 duration-500">
                   {h.type === 'Optional' ? <Sparkles size={80} /> : <Globe size={80} />}
                </div>

                {/* Top Row: Date & Status */}
                <div className="flex justify-between items-start mb-6 relative z-10">
                   <div className="flex flex-col items-center justify-center w-16 h-16 bg-slate-50 dark:bg-white/5 rounded-2xl border border-slate-100 dark:border-white/5 group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
                      <span className="text-[9px] font-black uppercase text-slate-400">{h.date.split(' ')[0]}</span>
                      <span className="text-xl font-black text-slate-900 dark:text-white leading-none mt-0.5">{h.date.split(' ')[1]}</span>
                   </div>
                   <TypeBadge type={h.type} />
                </div>

                {/* Content */}
                <div className="relative z-10">
                   <h3 className="text-lg font-black text-slate-900 dark:text-white uppercase tracking-tight mb-2 group-hover:text-brand-600 transition-colors">
                     {h.name}
                   </h3>
                   
                   <div className="space-y-2">
                      <div className="flex items-center gap-2">
                         <Calendar size={12} className="text-slate-400" />
                         <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide">
                            {h.day}, {h.year}
                         </span>
                      </div>
                      
                      <div className="flex items-center gap-2">
                         <MapPin size={12} className="text-slate-400" />
                         <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            {h.country} • <span className="text-slate-500 dark:text-slate-300">{h.region}</span>
                         </span>
                      </div>
                   </div>
                </div>

                {/* Bottom Accent Line */}
                <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-brand-500 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
             </div>
           )) : (
             <div className="col-span-full py-20 text-center rounded-[2rem] border-2 border-dashed border-slate-200 dark:border-slate-800">
                <Filter className="w-10 h-10 text-slate-300 mx-auto mb-4" />
                <p className="text-sm font-black uppercase text-slate-400 tracking-widest">No holidays match this criteria.</p>
             </div>
           )}
        </div>

      </div>
    </div>
  );
}

/* --- COMPONENTS --- */

const FilterDropdown = ({ icon, value, onChange, options, placeholder }: any) => (
  <div className="relative flex-1 group">
     <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-hover:text-brand-500 transition-colors">{icon}</div>
     <select 
       value={value}
       onChange={(e) => onChange(e.target.value)}
       className="w-full bg-slate-50 dark:bg-white/5 appearance-none rounded-xl py-3.5 pl-10 pr-8 text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-brand-500/50 cursor-pointer hover:bg-slate-100 dark:hover:bg-white/10 transition-all"
     >
       {placeholder && <option value="All">{placeholder}</option>}
       {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
     </select>
     <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
  </div>
);

const StatItem = ({ label, value }: any) => (
  <div className="px-4 text-center min-w-[60px]">
     <div className="text-lg font-black text-slate-900 dark:text-white leading-none">{value}</div>
     <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-1">{label}</div>
  </div>
);

const TypeBadge = ({ type }: { type: string }) => {
  const isOptional = type === "Optional";
  return (
    <span className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
      isOptional 
      ? "bg-amber-100 text-amber-600 dark:bg-amber-500/10 dark:text-amber-500 border border-amber-200 dark:border-amber-500/20" 
      : "bg-emerald-100 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-500 border border-emerald-200 dark:border-emerald-500/20"
    }`}>
      {type}
    </span>
  );
};